-- Initial PostgreSQL deployment schema. Do not edit after a deployed migration.
CREATE TABLE analysis_task (
 id VARCHAR(36) PRIMARY KEY,
 workspace VARCHAR(64) NOT NULL,
 idem VARCHAR(128) NOT NULL,
 request_json TEXT NOT NULL,
 dataset_base64 TEXT NOT NULL,
 source_sha VARCHAR(64) NOT NULL,
 created_at BIGINT NOT NULL,
 status VARCHAR(16) NOT NULL CHECK (status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')),
 attempt INTEGER NOT NULL DEFAULT 0,
 lease_token VARCHAR(36),
 lease_until BIGINT NOT NULL DEFAULT 0,
 available_at BIGINT NOT NULL DEFAULT 0,
 result_json TEXT,
 result_hash VARCHAR(64),
 error_code VARCHAR(80),
 category VARCHAR(16) NOT NULL DEFAULT 'analysis',
 expires_at BIGINT NOT NULL DEFAULT 0,
 CONSTRAINT task_idempotency UNIQUE(workspace,idem)
);
CREATE INDEX task_ready ON analysis_task(status,available_at,lease_until);
CREATE INDEX task_expiry ON analysis_task(status,expires_at);
CREATE TABLE task_event (
 sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 task_id VARCHAR(36) NOT NULL REFERENCES analysis_task(id),
 event_at BIGINT NOT NULL,
 kind VARCHAR(32) NOT NULL,
 attempt INTEGER NOT NULL
);
CREATE TABLE dataset_import_guard (
 workspace VARCHAR(64) PRIMARY KEY,
 worker_last_poll_at BIGINT NOT NULL DEFAULT 0
);
INSERT INTO dataset_import_guard(workspace) VALUES ('demo-shop');
CREATE TABLE dataset_import (
 id VARCHAR(36) PRIMARY KEY,
 workspace VARCHAR(64) NOT NULL,
 idem VARCHAR(128) NOT NULL,
 upload_hash VARCHAR(64) NOT NULL,
 name VARCHAR(120) NOT NULL,
 files_json TEXT NOT NULL,
 mapping_json TEXT NOT NULL DEFAULT 'null',
 created_at BIGINT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 0,
 check_task_id VARCHAR(36),
 version_id VARCHAR(80),
 archived BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT import_idempotency UNIQUE(workspace,idem)
);
CREATE TABLE dataset_check (
 task_id VARCHAR(36) PRIMARY KEY REFERENCES analysis_task(id),
 draft_id VARCHAR(36) NOT NULL REFERENCES dataset_import(id),
 revision INTEGER NOT NULL,
 report_json TEXT NOT NULL,
 mapping_json TEXT NOT NULL,
 snapshot_base64 TEXT,
 snapshot_sha VARCHAR(64),
 review_sha VARCHAR(64) NOT NULL
);
CREATE TABLE dataset_version (
 id VARCHAR(80) PRIMARY KEY,
 workspace VARCHAR(64) NOT NULL,
 draft_id VARCHAR(36) NOT NULL REFERENCES dataset_import(id),
 check_task_id VARCHAR(36) NOT NULL REFERENCES dataset_check(task_id),
 metadata_json TEXT NOT NULL,
 snapshot_base64 TEXT NOT NULL,
 snapshot_sha VARCHAR(64) NOT NULL,
 model_allowed BOOLEAN NOT NULL,
 created_at BIGINT NOT NULL
);
